policy_budget.code:
def policy_budget(sdk, requested):
    state = sdk.get_state()
    return max(0, min(requested, state["max_steps"] - state["steps_used"]))

actuate_gripper.code:
def actuate_gripper(sdk, action, ticks):
    budget = remaining_steps(sdk)
    if budget > 0:
        sdk.set_gripper(action, steps=min(ticks, budget))

remaining_steps.code:
def remaining_steps(sdk):
    state = sdk.get_state()
    return max(0, min(400, state["max_steps"]) - state["steps_used"])
